using System;using System.Drawing;using System.IO;using System.Linq;using System.Windows.Forms;
namespace ServiceTool{internal static class SettingsFooterLayoutTests{
static System.Collections.Generic.IEnumerable<Control> Walk(Control p){foreach(Control c in p.Controls){yield return c;foreach(var n in Walk(c))yield return n;}}
[STAThread]static int Main(){int count=0;try{foreach(bool dark in new[]{false,true})foreach(Size size in new[]{new Size(1060,720),new Size(1366,768),new Size(1920,1080),new Size(800,1100)})using(var f=new InitialSystemSettingsForm(true)){f.SetTheme(dark,false);f.Show();f.MinimumSize=Size.Empty;f.ClientSize=size;for(int i=0;i<25;i++)Application.DoEvents();var all=Walk(f).ToArray();var back=all.OfType<BrandButton>().Single(b=>b.Text=="В меню");var log=all.OfType<JournalTextBox>().Single();var card=log.Parent.Parent;var status=all.OfType<Label>().Single(l=>l.Parent==back.Parent);Func<Control,int> cy=c=>c.PointToScreen(new Point(0,c.Height/2)).Y;if(Math.Abs(cy(status)-cy(back))>2)throw new Exception("Footer centres differ");count++;if(back.PointToScreen(Point.Empty).Y-card.PointToScreen(new Point(0,card.Height)).Y>32)throw new Exception("Blank area below journal");count++;if(card.Height<64)throw new Exception("Journal clipped");count++;if(f.FormBorderStyle!=FormBorderStyle.FixedSingle||!f.MaximizeBox)throw new Exception("Window policy");count++;using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"settings-footer-"+dark+"-"+size.Width+"x"+size.Height+".png"));}f.Close();}Console.WriteLine("PASS: "+count+" settings footer/journal/window policy assertions; no settings applied.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}}
